---RefreshBoardByGoodsId 根据道具id刷新提示板
---@param goodsId integer @ 道具id
---@param showAmount boolean @ 是否显示玩家持有道具的数量
---@param amount integer @ 外部传入的道具数量
function CommonTipsBoardGoods:RefreshBoardByGoodsId(goodsId, showAmount, amount)
    -- 设置是否显示数量
    if nil ~= amount then
        -- 外部传入数量时必定显示
        self:ShowAmount(true)
    else
        self:ShowAmount(showAmount)
    end

    local type = GoodsUtils.GetIdType(goodsId)
    ---@type GoodsVo
    local goodsVo
    if type == Constants.IDType.GoodsBattleFood then
        local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
        goodsVo = CookingUtils.GetBattleCookingFoodVo(goodsId)
    elseif type == Constants.IDType.GoodsFavorableFood then
        local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
        goodsVo = CookingUtils.GetOrderFoodVo(goodsId)
    else
        goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    end

    if isNull(goodsVo) then
        -- 未找到道具配置
        self:RefreshBoardByContent(goodsVo,
                checkString(goodsId),
                string.format('%s%s', localize('未找到道具配置'), 0)
        )
    else
        self:FillJumpWay(goodsVo)

        -- 找到道具配置
        local amount_ = 0
        if nil ~= amount then
            -- 外部传入的数量
            amount_ = amount
        elseif true == showAmount then
            -- 玩家持有的数量
            amount = checkInt(GoodsUtils.GetThingNo(goodsId))
        end

        -- 刷新
        self:RefreshBoardByGoodsVo(goodsVo, amount)
    end

    local CountRt = CfUtils.GetNodeRect(self.Content)
    if CountRt.height < 482 then
        self.ScrollView.sizeDelta = Vector2.New(self.ScrollView.sizeDelta.x, CountRt.height)
    else
        self.ScrollView.sizeDelta = Vector2.New(self.ScrollView.sizeDelta.x, 482)
    end
end

function CommonTipsBoardGoods:FillJumpWay(goodsVo)
    local type = GoodsUtils.GetIdType(goodsVo.id)
    if type == Constants.IDType.GoodsBattleFood or type == Constants.IDType.GoodsFavorableFood then
        goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsVo.menu)
    end
    
    ---添加获取途径的逻辑
    if isSet(goodsVo, "jumpAway") and table.count(goodsVo.jumpAway) > 0 then
        ---存在获取途径
        local parentGo = self.Content.gameObject
        ---@type GoodsConfMgr
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        local questConfMgr = QuestConfMgr:GetInstance()
        --@type Engine.UI.UIDialog
        local lastDialog = CS.Engine.UI.UIModule.CurrentScreen:LastDialog()
        local lastId = 0
        if isNotNull(lastDialog) then
            lastId =  lastDialog.Argument.id    
        end
        for i, v in pairs(goodsVo.jumpAway) do
            ---@type TableML.TableFileRow
            local row = goodsConfMgr:GetJumpModuleRow(v)
            local moduleId = checkInt(row:Get("moduleID"))
            if moduleId ~= lastId then
                local go = KTool.Instantiate(parentGo, self.OpenAwayNode.gameObject)
                KTool.SetActive(go, true)
                go.name = moduleId
                go = go.transform:Find("OpenAwayNodePrefab")
                local textTrans = go.transform:Find("Text")
                local buttonTrans = go.transform:Find("FontStyleButton")
                CfUtils.FillText(buttonTrans.transform:Find("Text"), localize("前往"))
                local functionName = parse_localizeText(row, "functionName", "")
                local extraPara = nil
                if moduleId <= 0 then
                    KTool.SetActive(buttonTrans.gameObject, false)
                else
                    KTool.SetActive(buttonTrans.gameObject, true)
                    if goodsVo.jumpParameter and #goodsVo.jumpParameter > 0 then
                        ---存在跳转参数的情况时需要指定关卡信息
                        local questId = goodsVo.jumpParameter[i]
                        if not isNull(questId) then
                            local questType = GoodsUtils.GetIdType(questId)
                            if questType == Constants.IDType.QuestMain then
                                ---主线
                                ---@type QuestMainVo
                                local vo = questConfMgr:GetQuestVoById(questId)
                                if isTable(vo) then
                                    functionName = string.format('%s(%s)', functionName, vo.label)
                                end
                            elseif questType == Constants.IDType.QuestDaily or questType == Constants.IDType.QuestCoinsCopy or questType == Constants.IDType.QuestExpCopy or questType == Constants.IDType.QuestUpStarCopy then
                                ---副本
                                ---@type QuestDailyVo
                                local vo = questConfMgr:GetQuestVoById(questId)
                                if isTable(vo) then
                                    functionName = string.format('%s(%s)', functionName, vo.label)
                                end
                            elseif questType == Constants.IDType.RestaurantRecipeGoods then
                                extraPara = goodsVo.jumpParameter
                            end
                        end
                    end
                end
                local functionID = checkNumber(row:Get("functionID"))
                local isUnlock = GameUtils.IsUnlockedBySystemTogId(functionID)
                local isCanJump = goodsConfMgr:CheckIsCanJump(row,false)
                --区域拿参数判断  特殊
                if functionID == Constants.SystemToggleIds.Id2001 then
                    local t = checkTable(CfUtils.Split(checkString(row:Get("parameter"))))
                    local regionId = checkNumber(t[1])
                    if regionId > 0 then
                        isUnlock = ActionUtils.IsUnlockRegionalSecondPoint(regionId)
                    end
                end
    
                if isUnlock and isCanJump then
                else
                    buttonTrans.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B14")
                end
    
                KTool.GetComponent(textTrans.gameObject, typeof(Text)).text = functionName
                UIEventProxy.Create(buttonTrans.gameObject).onPointerClick = function()
                    ---跳转按钮的事件的逻辑
                    goodsConfMgr:ExecuteJump(row, goodsVo, i,nil,extraPara)
                end
            end
        end
        KTool.SetActive(self.NoWayNode.gameObject, false)
    else
        ---不存在时
        KTool.SetActive(self.NoWayNode.gameObject, true)
    end
end

---RefreshBoardByGoodsVo 根据道具vo刷新提示板
---@param goodsVo GoodsVo @ 道具配表信息
---@param amount integer @ 道具数量
function CommonTipsBoardGoods:RefreshBoardByGoodsVo(goodsVo, amount)
    local type = GoodsUtils.GetIdType(goodsVo.id)
    local desc
    --战斗料理特殊处理下
    if type == Constants.IDType.GoodsBattleFood then
        local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
        local t = {}
        local t1= CookingUtils.GetBattleFoodEffectDesc(goodsVo.id)
        local t2 = CfUtils.Split(goodsVo.desc, ";")
        --table.insert(t, t1[1])
        for k, v in pairs(t2) do
            table.insert(t, v)
        end

        desc = localize("食用效果:\n")
        for k, v in pairs(t) do
            desc = desc..v
            if k < table.count(t) then
                desc = desc.."\n"
            end
        end
    else
        desc = goodsVo.desc
    end
    self:RefreshBoardByContent(goodsVo, goodsVo.name, desc, amount, goodsVo.description)


    CfUtils.RefeshGoodGo2(self.GoodNode, goodsVo.id, nil, nil, nil, function()
        
    end, nil, {isTips = 1})
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4070, "GoodsShowTypeVo", goodsVo.showType)
    local isShowStar = false
    if not isNull(vo) then
        isShowStar = (checkNumber(vo.showStar) == 1)
        CfUtils.FillText(self.TxtMaterial, vo.name)
        CfUtils.SetActive(self.StarGroup, isShowStar)
    else
        CfUtils.SetActive(self.StarGroup, false)
    end
    if isShowStar then
        local num = checkNumber(goodsVo.quality)
        for i = 1, num do
            local go = CfUtils.InstantiateGo(self.ImgStar, self.StarGroup)
            CfUtils.SetActive(go, true)
        end

        local goodStar = self.GoodNode:Find("Container/Layout/GoodStar")
        if isNotNull(goodStar) then
            CfUtils.SetActive(goodStar, false)
        end
        local icon = self.GoodNode:Find("Container/Icon")
        if isNotNull(icon) then
            icon.transform.localPosition = Vector3.New(icon.transform.localPosition.x, icon.transform.localPosition.y - 18, icon.transform.localPosition.z)
        end
    end
end

---RefreshBoardByContent 根据内容刷新提示板
---@param goodsVo GoodsVo @ 道具id
---@param titleText string @ 标题文字
---@param descText string @ 一段描述
---@param contentText string @ 内容文字
---@param amount integer @ 道具数量
function CommonTipsBoardGoods:RefreshBoardByContent(goodsVo, titleText, contentText, amount, descText)
    -- 刷新文字
    local mb = GetLuaBehaviour(self.TitleNode.gameObject, TitleNodePath)
    if not isNull(mb) then
        if not KTool.IsNull(mb.Env) then
            ---@type CommonTitleNode
            local env = mb.Env
            local rare
            -- 标题颜色不显示了
            --if checkInt(goodsVo.quality) > 0 then
            --    rare = checkInt(goodsVo.quality)
            --end
            env:RefreshUI(titleText, rare)
        end
    end
    CfUtils.FillText(self.ContentTxt2, contentText)
    CfUtils.FillText(self.ContentTxt, descText)

    if KTool.IsActive(self.NumTxt.gameObject) then
        --self.NumTxt.text = string.format('%s %s', localize('库存'), checkString(amount))
        --self.NumTxt.text = string.format('x%s', FormatCurrencyNum(amount))
        --self.NumTxt.text = string.format('%s:%s', localize('拥有'), amount)
        self.NumTxt.text = localize('拥有')
        self.TextNumber.text = checkNumber(amount)

        --self.NumTxt:GetComponent(_ContentSizeFitter):SetLayoutHorizontal()
    end

    -- 刷新layout
    self.ContentTxt:GetComponent(_ContentSizeFitter):SetLayoutVertical()
    self.ContentTxt2:GetComponent(_ContentSizeFitter):SetLayoutVertical()
    --self.Bg:GetComponent(_ContentSizeFitter):SetLayoutVertical()
end

---ShowAmount 显示玩家的道具数量
---@param show boolean 是否显示
function CommonTipsBoardGoods:ShowAmount(show)
    KTool.SetActive(self.NumTxt.gameObject, checkBool(show))
    KTool.SetActive(self.TextNumber.gameObject, checkBool(show))
end

